mapper.select:
SELECT
FROM employee e LEFT JOIN department d ON e.department_id = d.id LEFT JOIN workposition p ON e.position_id = p.id LEFT JOIN employee_grade eg ON e.grade_id = eg.id LEFT JOIN employee creator ON e.created_by = creator.id
ORDER BY
${query.sortField}
${query.sortDirection}
e.entry_date DESC, e.created_at DESC
LIMIT #{query.offset}, #{query.size}

